package yagen.waitmydawn.kb.service;
import com.fasterxml.jackson.databind.JsonNode;
import java.io.IOException;
import java.util.*;

/** 组成完整性与像素可见性独立验证；旧快照不补造完整性结论。 */
final class EntityCompositionInfo {
 static void validate(JsonNode row)throws IOException {
  if(!row.has("composition"))return;var c=row.path("composition");if(!c.isObject()||c.path("schemaVersion").asInt()!=1||!Set.of("COMPLETE","PARTIAL","UNVERIFIED").contains(c.path("status").asText())||!c.path("rootVisibleExpected").isBoolean()||!c.path("extra").isObject()||c.path("extra").toString().length()>16384||!c.path("reason").isTextual()||c.path("reason").asText().length()>4000||!c.path("adapterVersion").isTextual()||c.path("adapterVersion").asText().isBlank()||c.path("adapterVersion").asText().length()>64)throw new IOException("实体组成描述无效");resourceId(c.path("adapter").asText());var parts=c.path("parts");if(!parts.isArray()||parts.size()>128)throw new IOException("实体部件数量无效");var depths=new HashMap<String,Integer>();depths.put("root",0);
  for(var part:parts){String key=part.path("key").asText(),parent=part.path("parent").asText();if(!key.matches("[a-zA-Z0-9_.-]{1,80}")||depths.containsKey(key)||!depths.containsKey(parent)||depths.get(parent)>=128||!Set.of("INDEPENDENT","PARENT_INCLUDED","COLLISION_ONLY","UNKNOWN").contains(part.path("policy").asText())||!part.path("transformSpace").asText().equals("ROOT_LOCAL"))throw new IOException("实体部件关系无效");if(!part.path("visibleExpected").isBoolean())throw new IOException("部件可见性声明无效");depths.put(key,depths.get(parent)+1);resourceId(part.path("id").asText());double length=0;for(String axis:List.of("x","y","z","yaw","pitch","bodyYaw","headYaw")){var n=part.path(axis);if(!n.isNumber()||!Double.isFinite(n.asDouble()))throw new IOException("实体部件变换无效");if(axis.length()==1)length+=n.asDouble()*n.asDouble();}if(length>65536)throw new IOException("实体部件偏移过大");if(!part.path("dataHash").asText().matches("[0-9a-f]{64}")||!(part.path("syncedHash").asText().equals("not-rendered")||part.path("syncedHash").asText().matches("[0-9a-f]{64}")))throw new IOException("实体部件摘要无效");if(part.path("policy").asText().equals("UNKNOWN")&&c.path("status").asText().equals("COMPLETE"))throw new IOException("未知部件不能声明完整");}
  var check=row.path("compositionRender");var independent=new HashSet<String>();var expected=new HashSet<String>();if(c.path("rootVisibleExpected").asBoolean())expected.add("root");for(var part:parts)if(part.path("policy").asText().equals("INDEPENDENT")){independent.add(part.path("key").asText());if(part.path("visibleExpected").asBoolean())expected.add(part.path("key").asText());}
  if(!check.isObject()||!Set.of("COMPLETE","PARTIAL","NOT_REQUIRED").contains(check.path("status").asText())||!check.path("total").isIntegralNumber()||check.path("total").asInt()!=independent.size()+1||!check.path("noVisiblePixels").isArray())throw new IOException("实体部件像素验证缺失或无效");var missing=new HashSet<String>();for(var key:check.path("noVisiblePixels"))if(!key.isTextual()||!expected.contains(key.asText())||!missing.add(key.asText()))throw new IOException("无效的缺失部件键");if(check.path("status").asText().equals("NOT_REQUIRED")&&(!expected.isEmpty()||!missing.isEmpty()))throw new IOException("可见模型不能声明无需验证");if(!check.path("status").asText().equals("NOT_REQUIRED")&&(check.path("status").asText().equals("COMPLETE")!=missing.isEmpty()))throw new IOException("部件可见性结论不一致");
  var state=row.path("state").path("traits").path("composition");if(!state.isMissingNode()&&!state.equals(c))throw new IOException("组成状态与图片描述不一致");
 }
 private static void resourceId(String id)throws IOException {try{yagen.waitmydawn.kb.model.RecipePlan.resourceId(id);}catch(IllegalArgumentException invalid){throw new IOException("组成注册名无效",invalid);}}
 static String caption(JsonNode row){if(!row.has("composition"))return "";var c=row.path("composition");String context=row.path("renderBackend").asText().equals("STATIC_BASE_MODEL")?"；静态基础模型（未复现原特效）":"";if(row.path("renderBackend").asText().equals("CREATE_CPU_STANDARD"))context+="；CPU包裹模型展示（未指定样式时采用标准样式）";if(row.path("compositionRender").path("status").asText().equals("NOT_REQUIRED"))context+="；当前状态未要求可见像素，不能据此证明正常外观";if(c.path("extra").path("presentation").asText().equals("STANDARD_ASSEMBLED"))context+="；标准展示组合";if(row.path("compositionRender").path("status").asText().equals("PARTIAL"))return context+"；部分外观：预期模型未取得可见像素 "+row.path("compositionRender").path("noVisiblePixels");return context+switch(c.path("status").asText()){case "COMPLETE"->"；组成已验证（"+c.path("parts").size()+" 个部件）";case "PARTIAL"->"；部分外观："+c.path("reason").asText();default->"；组成完整性未验证";};}
}
